contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a) public payable {
        require(true);

        bool s1 = c.setOwner(a); if (__ESBMC_reverted()) return;
        address after1 = c.owner(); if (__ESBMC_reverted()) return;

        bool s2 = c.setOwner(a); if (__ESBMC_reverted()) return;
        address after2 = c.owner(); if (__ESBMC_reverted()) return;

        assert(s1 && s2 && after1 == after2);
    }

    receive() external payable {}
}

